#!/usr/bin/env bash
# СУДИТ: skills/init-project/SKILL.md scripts/project-conformance.sh
# СУД: свойство мира
# probe_D1016.sh — проект, инициированный раньше части договора, эту часть получает (D1016).
#
# Коды: 0 — в каждом живом инициированном проекте (есть SESSION.md, шаг 3 инициации, и он правлен за последние
#       30 дней — заброшенные не в счёте, решение владельца 23 октября 2026) лежат части нынешнего
#       договора: BACKLOG.md с названным исполнителем архивирования (backlog-archive.sh) и ROOTS.md;
#       1 — у кого-то части нет (печатается, у кого и какой); 2 — не измерено: нет каталога проектов
#       либо в нём нет ни одного инициированного.
# Повод — замечание владельца 21 октября 2026: «бэклог после инициации в проектах не заводится и
# правила архивирования». Корень (разбор того же дня): договор инициации растёт, а применяется к
# проекту один раз — при инициации. BACKLOG.md вошёл в договор 8 августа 2026, ROOTS.md — 11 сентября;
# в существующем проекте шаг 4 отдаёт создание аудиту, аудит (project-conformance.sh) называет
# отсутствие только при ручном запуске в проекте, и у его вывода нет исполнителя. Замер: пар
# «проект × часть, вошедшая в договор после его инициации» 12, части нет у 9, у трёх она вписана руками;
# у проекта, инициированного после обеих частей (blalb), есть обе.
# Каталог проектов — «$HOME/My Project», где проекты владельца лежат на деле. Перечень проектов ведёт и
# автосканер (из ~/.claude/projects), но на 20 октября 2026 он не восстановил путь у 32 из 49.
# Названный предел: судится мир, а не исполнитель — части, вписанные руками, позеленят пробу так же,
# как механизм переноса договора. Условие снятия: у переноса договора появится исполнимая часть, и
# проба станет судить её на проекте, собранном по старому договору.
set -uo pipefail

ROOT="$HOME/My Project"
[ -d "$ROOT" ] || { echo "НЕ ИЗМЕРЕНО: нет каталога проектов $ROOT" >&2; exit 2; }
n=0; bad=0
for p in "$ROOT"/*/; do
    p="${p%/}"
    [ -f "$p/SESSION.md" ] || continue
    # Заброшенный проект не в счёте (решение владельца 23 октября 2026): договор доезжает при старте сессии в
    # проекте, и у проекта без работы за 30 дней сессии не будет. Признак работы — свежесть SESSION.md.
    [ -n "$(find "$p/SESSION.md" -mtime -30 2>/dev/null)" ] || continue
    n=$((n + 1)); miss=""
    if [ ! -f "$p/BACKLOG.md" ]; then miss="BACKLOG.md"
    elif ! grep -q 'backlog-archive\.sh' "$p/BACKLOG.md" 2>/dev/null; then miss="исполнитель архивирования в BACKLOG.md"; fi
    [ -f "$p/ROOTS.md" ] || miss="${miss:+$miss, }ROOTS.md"
    [ -z "$miss" ] || { echo "${p##*/}: нет — $miss"; bad=$((bad + 1)); }
done
[ "$n" -gt 0 ] || { echo "НЕ ИЗМЕРЕНО: в $ROOT нет инициированных проектов (с SESSION.md)" >&2; exit 2; }
echo "инициированных проектов: $n, без частей нынешнего договора: $bad"
[ "$bad" -eq 0 ]
